83:   // Parse URL safely
84:   let parsedUrl;
85:   try {
86:     parsedUrl = new URL(req.url, `http://${req.headers.host || '127.0.0.1'}`);
87:   } catch (err) {
88:     return sendError(res, 400, 'Invalid Request URL');
89:   }
