94:     // 2. Route: GET /health or /api/health
95:     if (pathname === '/health' || pathname === '/api/health') {
96:       return sendJson(res, 200, {
97:         status: 'ok',
98:         uptime: process.uptime(),
99:         port: activePort,
100:         version: '1.0.0',
101:         timestamp: new Date().toISOString(),
