113:           servers: [
114:             { name: 'secret', '4k': true, status: 'ok' },
115:             { name: 'Nebula', '4k': false, status: 'ok' },
116:             { name: 'Lisbon', '4k': true, status: 'ok' },
117:             { name: 'Solara', '4k': false, status: 'ok' },
118:             { name: 'Athens', '4k': false, status: 'ok' },
119:           ],
120:         });
121:       }
122:     }
123: 
124:     // 4. Route: GET /api/stream
125:     if (pathname === '/api/stream') {
126:       const tmdbId = searchParams.get('tmdbId');
127:       const type = searchParams.get('type');
128:       const season = searchParams.get('season');
129:       const episode = searchParams.get('episode');
130:       const server = searchParams.get('server') || 'secret';
131: 
132:       if (!tmdbId || !type) {
133:         return sendError(res, 400, 'Missing required query parameters: tmdbId and type are required');
134:       }
135: 
136:       if (!/^\d+$/.test(tmdbId)) {
137:         return sendError(res, 400, 'Invalid tmdbId parameter: must be a positive integer');
138:       }
139: 
140:       if (type !== 'movie' && type !== 'tv') {
141:         return sendError(res, 400, "Invalid type parameter: must be 'movie' or 'tv'");
142:       }
143: 
144:       if (type === 'tv' && (!season || !episode)) {
145:         return sendError(res, 400, "Missing required query parameters: season and episode are required for type 'tv'");
146:       }
147: 
148:       const streamResult = await resolver.resolveStream({
149:         tmdbId,
150:         type,
151:         season,
152:         episode,
153:         server,
154:       });
155: 
156:       if (!streamResult || !streamResult.playlist) {
157:         return sendError(res, 502, 'Stream resolution failed: no playlist found');
158:       }
159: 
160:       // Construct local proxy stream URL
161:       const host = req.headers.host || `127.0.0.1:${activePort}`;
162:       const encodedPlaylist = encodeURIComponent(streamResult.playlist);
163:       const streamUrl = `http://${host}/hls/proxy?url=${encodedPlaylist}`;
164: 
165:       // Build subtitles array
166:       const subtitles = [];
167:       if (Array.isArray(streamResult.captions)) {
168:         for (const cap of streamResult.captions) {
169:           subtitles.push({
170:             label: cap.language || cap.id || 'English',
171:             srclang: cap.id || 'en',
172:             src: `http://${host}/proxy/sub?url=${encodeURIComponent(cap.url)}`,
173:           });
174:         }
175:       }
176: 
177:       // Query external subtitles from subs.wing.st
178:       try {
179:         const extSubs = await resolver.fetchSubtitles({ tmdbId, type, season, episode });
180:         if (Array.isArray(extSubs)) {
181:           for (const s of extSubs) {
182:             if (s.url && !subtitles.some(existing => existing.src.includes(encodeURIComponent(s.url)))) {
183:               subtitles.push({
184:                 label: s.display || s.language || 'External',
185:                 srclang: s.language || 'en',
186:                 src: `http://${host}/proxy/sub?url=${encodeURIComponent(s.url)}`,
187:               });
188:             }
189:           }
190:         }
191:       } catch (_) {
192:         // External subtitles failure is non-fatal
193:       }
194: 
195:       return sendJson(res, 200, {
196:         success: true,
197:         streamUrl,
198:         originalUrl: streamResult.playlist,
199:         server: streamResult.server || server,
200:         subtitles,
201:       });
202:     }
203: 
204:     // 5. Route: GET /hls/proxy
205:     if (pathname === '/hls/proxy') {
206:       const targetUrl = searchParams.get('url');
207:       if (!targetUrl) {
208:         return sendError(res, 400, "Missing 'url' query parameter for HLS proxy");
209:       }
210:       return hlsProxy.handleHlsProxy(req, res, targetUrl, activePort);
211:     }
212: 
213:     // 6. Route: GET /proxy/sub
214:     if (pathname === '/proxy/sub') {
215:       const subUrl = searchParams.get('url');
216:       if (!subUrl) {
217:         return sendError(res, 400, "Missing 'url' query parameter for subtitle proxy");
218:       }
219: 
220:       try {
221:         const subResponse = await fetch(subUrl, {
222:           headers: {
223:             'User-Agent': 'Mozilla/5.0 (Web0S; SmartTV) AppleWebKit/537.36 Chrome/108.0.5359.211',
224:             'Origin': 'https://cinejoy.pk',
225:             'Referer': 'https://cinejoy.pk/',
226:           },
227:           signal: AbortSignal.timeout(10000)
228:         });
229: 
230:         if (!subResponse.ok) {
231:           return sendError(res, 502, `Failed to fetch remote subtitle: ${subResponse.status} ${subResponse.statusText}`);
232:         }
233: 
234:         const rawText = await subResponse.text();
235:         const vttContent = convertSrtToVtt(rawText);
236:         const buffer = Buffer.from(vttContent, 'utf8');
237: 
238:         res.writeHead(200, {
239:           ...CORS_HEADERS,
240:           'Content-Type': 'text/vtt; charset=utf-8',
241:           'Content-Length': buffer.length,
242:         });
243:         return res.end(buffer);
244:       } catch (err) {
245:         return sendError(res, 502, 'Failed to fetch subtitle', err.message);
246:       }
247:     }
248: 
249:     // 7. Route: 404 Fallthrough
250:     return sendError(res, 404, 'Endpoint Not Found', { path: pathname });
251:   } catch (err) {
252:     console.error(`[cinejoy-server] Error handling ${req.method} ${pathname}:`, err);
253:     return sendError(res, 500, 'Internal Server Error', err.message);
254:   }
