301:           currentPort++;
302:           if (attempts >= MAX_PORT_ATTEMPTS) {
303:             return reject(new Error(`Could not bind to any port in range ${initialPort}-${currentPort - 1}`));
304:           }
305:           setTimeout(tryListen, 50);
306:         } else {
307:           reject(err);
308:         }
309:       });
310: 
311:       server.on('listening', () => {
312:         activeServer = server;
