314:         writeStatusFiles(activePort);
315:         console.log(`[cinejoy-server] Server running on http://${host}:${activePort} (PID: ${process.pid})`);
316:         resolve({ server, port: activePort });
317:       });
318: 
319:       server.listen(currentPort, host);
320:     }
321: 
322:     tryListen();
323:   });
324: }
