2:  * server/resolver.js - Stream Resolver Engine for cinejoy-webos
3:  * 
4:  * Executes WebAssembly crush.wasm request sealing, binary POST to api.wing.st/g,
5:  * AES-256-GCM response decryption, and multi-server fallback resolution.
6:  */
7: 
8: const crypto = require('crypto');
9: const fs = require('fs');
10: const path = require('path');
