const fs = require('fs');

async function testWasmAndCryptoOnTv() {
  const pages = await (await fetch('http://192.168.1.15:9998/json')).json();
  const wsUrl = pages[0].webSocketDebuggerUrl;
  const ws = new WebSocket(wsUrl);

  function evalInBrowser(expr) {
    return new Promise((resolve) => {
      const id = Math.floor(Math.random() * 100000);
      const onMsg = (event) => {
        const data = JSON.parse(event.data);
        if (data.id === id) {
          ws.removeEventListener('message', onMsg);
          resolve(data.result);
        }
      };
      ws.addEventListener('message', onMsg);
      ws.send(JSON.stringify({
        id,
        method: 'Runtime.evaluate',
        params: { expression: expr, awaitPromise: true, returnByValue: true }
      }));
    });
  }

  ws.onopen = async () => {
    console.log('Testing WASM and WebCrypto on TV browser...');

    // Load crush.wasm binary from local machine and base64 encode it to pass into TV browser
    const wasmBase64 = fs.readFileSync('./server/crush.wasm').toString('base64');

    const testScript = \`
      (async () => {
        try {
          const b64 = '\${wasmBase64}';
          const binaryString = atob(b64);
          const bytes = new Uint8Array(binaryString.length);
          for (let i = 0; i < binaryString.length; i++) {
            bytes[i] = binaryString.charCodeAt(i);
          }

          // 1. Compile WASM
          const wasmModule = await WebAssembly.compile(bytes.buffer);
          const wasmInstance = await WebAssembly.instantiate(wasmModule);
          const exports = wasmInstance.exports;

          // 2. Prepare payload
          const payloadObj = { tmdb: '27205' };
          const payloadJson = JSON.stringify({
            path: '/secret/movie',
            payload: payloadObj
          });
          const enc = new TextEncoder();
          const encodedPayload = enc.encode(payloadJson);

          const randBytes = new Uint8Array(44);
          crypto.getRandomValues(randBytes);

          const payloadPtr = exports.alloc(encodedPayload.length);
          const randPtr = exports.alloc(randBytes.length);
          const outPtr = exports.alloc(4096);

          const mem = new Uint8Array(exports.memory.buffer);
          mem.set(encodedPayload, payloadPtr);
          mem.set(randBytes, randPtr);

          const sealedLen = exports.seal_request(
            payloadPtr, encodedPayload.length,
            randPtr, randBytes.length,
            outPtr, 4096
          );

          if (sealedLen <= 98) {
            return { error: 'Invalid sealed length: ' + sealedLen };
          }

          const sealedBuf = new Uint8Array(exports.memory.buffer, outPtr, sealedLen);
          const responseKey = sealedBuf.slice(0, 32);
          const keyId = sealedBuf[32];
          const ephemeralPublic = sealedBuf.slice(33, 98);
          const ciphertextBody = sealedBuf.slice(98, sealedLen);

          // Free
          exports.dealloc(payloadPtr, encodedPayload.length);
          exports.dealloc(randPtr, randBytes.length);
          exports.dealloc(outPtr, 4096);

          // 3. Dispatch to api.wing.st/g from TV browser
          const res = await fetch('https://api.wing.st/g', {
            method: 'POST',
            headers: {
              'Content-Type': 'text/plain;charset=UTF-8'
            },
            body: ciphertextBody
          });

          if (!res.ok) {
            return { error: 'Gateway returned HTTP ' + res.status };
          }

          const respArrBuf = await res.arrayBuffer();
          const respBuf = new Uint8Array(respArrBuf);

          if (respBuf.length < 28) {
            return { error: 'Response too short: ' + respBuf.length };
          }

          // 4. Decrypt via Web Cryptography API (crypto.subtle)
          const iv = respBuf.slice(0, 12);
          const ciphertextWithTag = respBuf.slice(12); // in WebCrypto AES-GCM, the auth tag is at the end of ciphertext

          // AAD: 'lumen-gate-v2' + [0, 2, keyId] + ephemeralPublic
          const protoBytes = enc.encode('lumen-gate-v2');
          const aad = new Uint8Array(protoBytes.length + 3 + ephemeralPublic.length);
          aad.set(protoBytes, 0);
          aad.set([0, 2, keyId], protoBytes.length);
          aad.set(ephemeralPublic, protoBytes.length + 3);

          const cryptoKey = await crypto.subtle.importKey(
            'raw',
            responseKey,
            { name: 'AES-GCM' },
            false,
            ['decrypt']
          );

          const decryptedArrBuf = await crypto.subtle.decrypt(
            {
              name: 'AES-GCM',
              iv: iv,
              additionalData: aad,
              tagLength: 128
            },
            cryptoKey,
            ciphertextWithTag
          );

          const decText = new TextDecoder().decode(decryptedArrBuf);
          const decJson = JSON.parse(decText);

          return {
            success: true,
            status: decJson.status,
            playlist: decJson.data?.stream?.[0]?.playlist,
            server: decJson.data?.stream?.[0]?.server || 'secret'
          };
        } catch (err) {
          return { error: err.message, stack: err.stack };
        }
      })()
    \`;

    const result = await evalInBrowser(testScript);
    console.log('WASM & WebCrypto execution result in TV browser:');
    console.log(JSON.stringify(result, null, 2));

    ws.close();
    process.exit(0);
  };
}
testWasmAndCryptoOnTv();
